/**
 * Facade generator — BUILD-TIME script.
 *
 * Reads spec-index.json (already generated by index-builder.ts) and generates
 * src/client/generated/facade.ts — a namespaced typed client aggregating all
 * allowed operations into ergonomic method calls:
 *
 *   api.analytics.getCashFlowSummary(params)
 *   api.transactions.updateTransactionCategory(id, body)
 *
 * Types are imported from @boostedbudget/api-client/src/models so the facade
 * stays in sync with the OpenAPI spec via the existing CI drift checks.
 *
 * Excluded operations are NOT generated into the facade (deny-by-default).
 * The host-proxy still enforces the manifest, but removing excluded ops from
 * the facade means they're unreachable at the TypeScript level too.
 *
 * Run via: bun run scripts/generate-facade.ts
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parse as parseYaml } from 'yaml'
import type { SpecIndex } from '../src/spec/search-runtime'

const __dirname = dirname(fileURLToPath(import.meta.url))
const SPEC_INDEX_PATH = resolve(__dirname, '../src/spec/generated/spec-index.json')
const OPENAPI_PATH = resolve(__dirname, '../../../api/openapi.yaml')
const OUTPUT_PATH = resolve(__dirname, '../src/client/generated/facade.ts')

const specIndex: SpecIndex = JSON.parse(readFileSync(SPEC_INDEX_PATH, 'utf-8'))
const rawYaml = readFileSync(OPENAPI_PATH, 'utf-8')
const spec = parseYaml(rawYaml) as {
  paths?: Record<string, Record<string, { operationId?: string; parameters?: unknown[] }>>
}

type MethodEntry = {
  operationId: string
  method: string
  path: string
  tag: string
}

const byTag = new Map<string, MethodEntry[]>()
for (const entry of specIndex.entries) {
  if (entry.excluded) continue
  const nsKey = tagToNs(entry.tags[0] ?? 'misc')
  if (!byTag.has(nsKey)) byTag.set(nsKey, [])
  byTag.get(nsKey)!.push({
    operationId: entry.operationId,
    method: entry.method,
    path: entry.path,
    tag: entry.tags[0] ?? 'misc',
  })
}

function tagToNs(tag: string): string {
  return tag
    .toLowerCase()
    .replace(/[^a-z0-9]+(.)/g, (_, c) => c.toUpperCase())
    .replace(/[^a-z0-9]/gi, '')
}

function opIdToMethodName(opId: string): string {
  return opId.replace(/-(\w)/g, (_, c) => c.toUpperCase())
}

function getOperationSpec(opId: string) {
  for (const pathItem of Object.values(spec.paths ?? {})) {
    for (const op of Object.values(pathItem)) {
      if (typeof op === 'object' && op && 'operationId' in op && op.operationId === opId) {
        return op as { parameters?: { in: string; name: string; required?: boolean }[]; requestBody?: unknown }
      }
    }
  }
  return null
}

function pathParamNames(path: string): string[] {
  return [...path.matchAll(/\{(\w+)\}/g)].map((m) => m[1])
}

function buildMethodSignature(entry: MethodEntry): string {
  const op = getOperationSpec(entry.operationId)
  const pathParams = pathParamNames(entry.path)
  const hasBody = ['POST', 'PUT', 'PATCH'].includes(entry.method)
  const hasQueryParams = op?.parameters?.some((p) => p.in === 'query') ?? false

  const args = [
    ...pathParams.map((p) => `${p}: string`),
    ...(hasQueryParams ? ['params?: Record<string, unknown>'] : []),
    ...(hasBody ? ['data?: unknown'] : []),
    'signal?: AbortSignal',
  ]

  let urlTemplate = entry.path
  for (const p of pathParams) {
    urlTemplate = urlTemplate.replace(`{${p}}`, `\${${p}}`)
  }
  const urlExpr = pathParams.length > 0 ? `\`${urlTemplate}\`` : `'${entry.path}'`

  const configFields = [
    `url: ${urlExpr}`,
    `method: '${entry.method}'`,
    ...(hasQueryParams ? ['params'] : []),
    ...(hasBody ? ['data'] : []),
    'signal',
  ]

  const methodName = opIdToMethodName(entry.operationId)
  return `      /** ${entry.method} ${entry.path} */
      ${methodName}(${args.join(', ')}): Promise<unknown> {
        return mutator({ ${configFields.join(', ')} })
      },`
}

let output = `/**
 * BoostedBudget API facade for Cloudflare Workers.
 * AUTO-GENERATED — do not edit manually.
 * Run: bun run scripts/generate-facade.ts
 *
 * Contains only allowed operations (excluded ops are absent).
 * All calls are routed through the fetch mutator which injects
 * Authorization + X-Origin-Secret per request.
 */

import type { FetchMutator } from '../fetch-mutator'

export function createApiClient(mutator: FetchMutator) {
  return {
`

for (const [ns, methods] of [...byTag.entries()].sort()) {
  output += `    ${ns}: {\n`
  for (const method of methods) {
    output += buildMethodSignature(method) + '\n'
  }
  output += `    } as const,\n`
}

output += `  } as const
}

export type ApiClient = ReturnType<typeof createApiClient>
`

writeFileSync(OUTPUT_PATH, output)
const total = [...byTag.values()].reduce((acc, arr) => acc + arr.length, 0)
console.log(`✅ facade.ts generated: ${total} operations across ${byTag.size} namespaces`)
